import { createReadStream, createWriteStream } from 'node:fs';
import { mkdir, rename, rm } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { DeleteObjectCommand, GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';

/** Where attachment bytes live. Keys are generated by the platform (`yyyy/mm/<uuid>`), never user input. */
export interface BlobStorage {
  readonly kind: 'local' | 's3';
  /** Writes the file at `path` (a finished temp file) under `key`. */
  put(key: string, path: string, info: { contentType: string; size: number }): Promise<void>;
  get(key: string): Promise<Readable>;
  delete(key: string): Promise<void>;
}

const KEY = /^[0-9]{4}\/[0-9]{2}\/[0-9a-f-]{36}$/;

function assertKey(key: string) {
  if (!KEY.test(key)) throw new Error(`invalid storage key "${key}"`);
}

/** A directory on disk (a mounted volume in containers). */
export class LocalStorage implements BlobStorage {
  readonly kind = 'local' as const;
  private readonly root: string;

  constructor(root: string) {
    this.root = resolve(root);
  }

  private path(key: string) {
    assertKey(key);
    const p = resolve(join(this.root, key));
    if (!p.startsWith(this.root + sep)) throw new Error('storage key escapes the root');
    return p;
  }

  async put(key: string, path: string) {
    const target = this.path(key);
    await mkdir(dirname(target), { recursive: true });
    const partial = `${target}.partial`;
    await pipeline(createReadStream(path), createWriteStream(partial, { flags: 'wx', mode: 0o640 }));
    await rename(partial, target);
  }

  async get(key: string): Promise<Readable> {
    return createReadStream(this.path(key));
  }

  async delete(key: string) {
    await rm(this.path(key), { force: true });
  }
}

export interface S3Options {
  bucket: string;
  region: string;
  endpoint?: string;
  forcePathStyle?: boolean;
  accessKeyId?: string;
  secretAccessKey?: string;
  prefix: string;
  /** Server-side encryption (`AES256` or `aws:kms`). */
  sse?: 'AES256' | 'aws:kms';
}

/** Amazon S3 or any S3-compatible store (MinIO, Ceph, …). Credentials fall back to the default chain. */
export class S3Storage implements BlobStorage {
  readonly kind = 's3' as const;
  private readonly client: S3Client;

  constructor(private readonly opts: S3Options) {
    this.client = new S3Client({
      region: opts.region,
      endpoint: opts.endpoint,
      forcePathStyle: opts.forcePathStyle,
      // Plain bodies: S3-compatible stores (MinIO, Ceph, …) don't all accept aws-chunked trailing checksums.
      requestChecksumCalculation: 'WHEN_REQUIRED',
      responseChecksumValidation: 'WHEN_REQUIRED',
      credentials:
        opts.accessKeyId && opts.secretAccessKey
          ? { accessKeyId: opts.accessKeyId, secretAccessKey: opts.secretAccessKey }
          : undefined,
    });
  }

  private key(key: string) {
    assertKey(key);
    return `${this.opts.prefix}${key}`;
  }

  async put(key: string, path: string, info: { contentType: string; size: number }) {
    await this.client.send(
      new PutObjectCommand({
        Bucket: this.opts.bucket,
        Key: this.key(key),
        Body: createReadStream(path),
        ContentLength: info.size,
        ContentType: info.contentType,
        ServerSideEncryption: this.opts.sse,
      }),
    );
  }

  async get(key: string): Promise<Readable> {
    const res = await this.client.send(
      new GetObjectCommand({ Bucket: this.opts.bucket, Key: this.key(key) }),
    );
    if (!res.Body) throw new Error('empty object body');
    return res.Body instanceof Readable ? res.Body : Readable.from(res.Body as AsyncIterable<Uint8Array>);
  }

  async delete(key: string) {
    await this.client.send(new DeleteObjectCommand({ Bucket: this.opts.bucket, Key: this.key(key) }));
  }
}
